#include <bits/stdc++.h>using namespace std;#define int long longinline void fmx(int &a,int b){ if(a<b) a=b;}#define go(i,a,b) for(int i=a;i<=b;i++)#define og(i,a,b) for(int i=b;i>=a;i--)#define all() a.begin() + 1,a.begin() + n + 1int T,n,ans; void O_o(){	ans = 0;	cin >> n;	auto calc = [&](int y) -> int {		int res = 0;		while(y){			res += y % 10;;			y /= 10;		}		return res;	};	for(int i=n;i<=n + 90;i++){		if(i - n == calc(i))ans++;	}	cout << ans << '\n';} signed main(){	ios::sync_with_stdio(false);	cin.tie(nullptr);cout.tie(nullptr);	cin >> T;	while(T--)O_o();}